/* Pixel-style quiz theme */
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --text: #e0e0e0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --border: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 20px;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 12px;
  padding: 32px 28px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 0 0 0 4px var(--accent), 0 0 20px rgba(233, 69, 96, 0.4);
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--border);
}

.question {
  font-size: 2rem;
  font-weight: bold;
  margin-bottom: 28px;
  min-height: 2.5rem;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.answer {
  background: var(--border);
  color: var(--text);
  border: 3px solid var(--accent);
  border-radius: 8px;
  padding: 14px 28px;
  font-size: 1.3rem;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.15s ease;
  min-width: 80px;
  box-shadow: 0 4px 0 var(--accent);
  position: relative;
  top: 0;
}

.answer:hover:not(:disabled) {
  background: var(--accent);
  color: var(--card);
  box-shadow: 0 4px 0 var(--accent-hover);
  top: -2px;
}

.answer:active:not(:disabled) {
  top: 2px;
  box-shadow: 0 2px 0 var(--accent);
}

.answer:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 3px;
}

.answer:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  box-shadow: none;
  top: 0;
}

.score {
  font-size: 1.2rem;
  margin-bottom: 24px;
  font-weight: bold;
  color: var(--accent);
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.control {
  background: transparent;
  color: var(--text);
  border: 3px solid var(--border);
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 1.1rem;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.15s ease;
  box-shadow: 0 3px 0 var(--border);
  position: relative;
  top: 0;
}

.control:hover:not(:disabled) {
  background: var(--border);
  border-color: var(--accent);
  color: var(--accent);
  box-shadow: 0 3px 0 var(--accent);
  top: -2px;
}

.control:active:not(:disabled) {
  top: 1px;
  box-shadow: 0 2px 0 var(--border);
}

.control:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 3px;
}

.control:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
  top: 0;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .question {
    font-size: 1.6rem;
  }
  .answer {
    padding: 12px 20px;
    font-size: 1.1rem;
    min-width: 70px;
  }
  .control {
    padding: 10px 18px;
    font-size: 1rem;
  }
}

// Pixel Quiz - offline two-question quiz
const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

let score = 0;
let currentQuestion = 0; // 0 = first, 1 = second, 2 = finished
let answered = false;

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

function updateScoreDisplay() {
  scoreEl.textContent = 'Score: ' + score;
}

function setAnswersEnabled(enabled) {
  answerA.disabled = !enabled;
  answerB.disabled = !enabled;
}

function loadQuestion(index) {
  if (index >= questions.length) {
    questionEl.textContent = 'Finished';
    setAnswersEnabled(false);
    nextBtn.disabled = true;
    return;
  }
  const q = questions[index];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  setAnswersEnabled(true);
  answered = false;
  nextBtn.disabled = true;
}

function handleAnswer(choice) {
  if (answered || currentQuestion >= questions.length) return;
  answered = true;
  setAnswersEnabled(false);
  nextBtn.disabled = false;
  if (choice === questions[currentQuestion].correct) {
    score += 1;
    updateScoreDisplay();
  }
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (currentQuestion < questions.length) {
    currentQuestion += 1;
    if (currentQuestion < questions.length) {
      loadQuestion(currentQuestion);
    } else {
      questionEl.textContent = 'Finished';
      setAnswersEnabled(false);
      nextBtn.disabled = true;
    }
  }
});

restartBtn.addEventListener('click', () => {
  score = 0;
  currentQuestion = 0;
  answered = false;
  updateScoreDisplay();
  loadQuestion(0);
});

// Initialize
updateScoreDisplay();
loadQuestion(0);
